//! `contracts/storage_operations_v1.json` (authored) -> the storage.v1
//! semantic-operation clients: `packages/tofu-db/src/generated_storage_operations.rs`,
//! `scripts/generated_storage_operations.py` and `tofu_db/generated_contract.py`.
//!
//! The three outputs' bytes are part of the storage contract identity the
//! application and its engine share (`serverctl_pkg.native_engine.
//! storage_contract_sha256` covers the engine's `generated_*.rs`), so their
//! text, including the `@generated by scripts/gen_storage_operation_catalog.py`
//! header, is frozen: changing a byte demands a new engine build for no
//! behaviour change. That script is still the catalog's checker (sidecar
//! registry == catalog, `operationsSha256`), like the catalog's own frozen
//! `generatedBy` key.

use serde_json::Value;

use crate::json::{array, boolean, field, integer, object, string};

pub const CONTRACT: &str = "contracts/storage_operations_v1.json";
pub const RUST_OUTPUT: &str = "packages/tofu-db/src/generated_storage_operations.rs";
pub const PYTHON_OUTPUT: &str = "scripts/generated_storage_operations.py";
pub const PACKAGE_PYTHON_OUTPUT: &str = "tofu_db/generated_contract.py";

pub fn load(text: &str) -> Result<Value, String> {
    serde_json::from_str(text).map_err(|error| format!("{CONTRACT}: {error}"))
}

/// The catalog's ASCII identifiers as Rust string literals (JSON escaping).
fn ascii_literal(value: &Value, what: &str) -> Result<String, String> {
    let text = string(value, what)?;
    if !text.is_ascii() {
        return Err(format!("Rust catalog identifier is not ASCII: {text:?}"));
    }
    serde_json::to_string(text).map_err(|error| error.to_string())
}

pub fn render_rust(document: &Value) -> Result<String, String> {
    let root = object(document, CONTRACT)?;
    let get = |key: &str| field(root, key, CONTRACT);
    let mut lines = vec![
        "//! @generated by scripts/gen_storage_operation_catalog.py; do not edit.".to_string(),
        String::new(),
        format!(
            "pub const STORAGE_SCHEMA_VERSION: u32 = {};",
            integer(get("sourceSchemaVersion")?, "sourceSchemaVersion")?
        ),
        format!(
            "pub const STORAGE_REGISTRY_VERSION: u32 = {};",
            integer(get("sourceRegistryVersion")?, "sourceRegistryVersion")?
        ),
        format!(
            "pub const STORAGE_OPERATION_COUNT: usize = {};",
            integer(get("operationCount")?, "operationCount")?
        ),
        "pub const STORAGE_OPERATIONS_SHA256: &str =".to_string(),
        format!(
            "    {};",
            ascii_literal(get("operationsSha256")?, "operationsSha256")?
        ),
        String::new(),
        format!(
            "pub const EVENT_READ_GUARD_CONTRACT: &str = {};",
            ascii_literal(get("eventReadGuardContract")?, "eventReadGuardContract")?
        ),
        format!(
            "pub const EVENT_READ_GUARD_SCOPED_CONTRACT: &str = {};",
            ascii_literal(
                get("eventReadGuardScopedContract")?,
                "eventReadGuardScopedContract"
            )?
        ),
        format!(
            "pub const EVENT_READ_GUARD_MAX_TYPES: usize = {};",
            integer(get("eventReadGuardMaxTypes")?, "eventReadGuardMaxTypes")?
        ),
    ];
    lines.extend(
        [
            "",
            "#[derive(Clone, Copy, Debug, Eq, PartialEq)]",
            "pub enum StorageOperationKind {",
            "    Query,",
            "    Command,",
            "    Maintenance,",
            "}",
            "",
            "impl StorageOperationKind {",
            "    pub const fn mutates_state(self) -> bool {",
            "        !matches!(self, Self::Query)",
            "    }",
            "}",
            "",
            "#[derive(Clone, Copy, Debug, Eq, PartialEq)]",
            "pub enum StorageOwnerScope {",
            "    HandlerEnforced,",
            "}",
            "",
            "#[derive(Clone, Copy, Debug, Eq, PartialEq)]",
            "pub struct StorageOperationMetadata {",
            "    pub name: &'static str,",
            "    pub domain: &'static str,",
            "    pub kind: StorageOperationKind,",
            "    pub receipt_required: bool,",
            "    pub receipt_when_true: Option<&'static str>,",
            "    pub transaction_timeout_millis: Option<u64>,",
            "    pub owner_scope: StorageOwnerScope,",
            "}",
            "",
            "pub static STORAGE_OPERATIONS: &[StorageOperationMetadata] = &[",
        ]
        .map(String::from),
    );
    for operation in array(get("operations")?, "operations")? {
        let operation = object(operation, "operations")?;
        let name = string(field(operation, "name", "operation")?, "operation name")?;
        let kind = match string(field(operation, "kind", name)?, name)? {
            "query" => "Query",
            "command" => "Command",
            "maintenance" => "Maintenance",
            other => return Err(format!("unknown operation kind: {other:?}")),
        };
        let timeout = match field(operation, "transactionTimeoutSeconds", name)? {
            Value::Null => "None".to_string(),
            value => {
                let seconds = value
                    .as_f64()
                    .ok_or_else(|| format!("invalid transaction timeout: {value}"))?;
                let millis = seconds * 1_000.0;
                if !millis.is_finite() || millis <= 0.0 || millis.fract() != 0.0 {
                    return Err(format!("invalid transaction timeout: {value}"));
                }
                format!("Some({})", millis as u64)
            }
        };
        let owner_scope = string(field(operation, "ownerScope", name)?, name)?;
        if owner_scope != "handler-enforced" {
            return Err(format!("unknown owner scope: {owner_scope:?}"));
        }
        let receipt_when_true = match operation.get("receiptWhenTrue") {
            Some(value) if crate::json::truthy(value) => {
                format!("Some({})", ascii_literal(value, "receiptWhenTrue")?)
            }
            _ => "None".to_string(),
        };
        lines.extend([
            "    StorageOperationMetadata {".to_string(),
            format!(
                "        name: {},",
                ascii_literal(field(operation, "name", name)?, name)?
            ),
            format!(
                "        domain: {},",
                ascii_literal(field(operation, "domain", name)?, name)?
            ),
            format!("        kind: StorageOperationKind::{kind},"),
            format!(
                "        receipt_required: {},",
                boolean(field(operation, "receiptRequired", name)?, name)?
            ),
            format!("        receipt_when_true: {receipt_when_true},"),
            format!("        transaction_timeout_millis: {timeout},"),
            "        owner_scope: StorageOwnerScope::HandlerEnforced,".to_string(),
            "    },".to_string(),
        ]);
    }
    lines.extend(
        [
            "];",
            "",
            "pub fn storage_operation(name: &str) -> Option<&'static StorageOperationMetadata> {",
            "    STORAGE_OPERATIONS",
            "        .binary_search_by_key(&name, |operation| operation.name)",
            "        .ok()",
            "        .map(|index| &STORAGE_OPERATIONS[index])",
            "}",
        ]
        .map(String::from),
    );
    Ok(lines.join("\n") + "\n")
}

/// The Python wire clients' schema version module (both Python outputs).
pub fn render_python(document: &Value) -> Result<String, String> {
    let root = object(document, CONTRACT)?;
    Ok(format!(
        "\"\"\"@generated by scripts/gen_storage_operation_catalog.py; do not edit.\"\"\"\n\
         \n# Source: contracts/storage_operations_v1.json (checked against the sidecar registry).\n\
         STORAGE_SCHEMA_VERSION = {}\n",
        integer(
            field(root, "sourceSchemaVersion", CONTRACT)?,
            "sourceSchemaVersion"
        )?
    ))
}
